[Expected Approach] Contribution of Each Element using Monotonic StacksInstead of calculating the min and max for each subarray individually, we calculate how much each element contributes to the sum of ranges.For each element in the array:Find the number of subarrays where it is the maximum.Find the number of subarrays where it is the minimum.The contribution of an element to the total sum is: contribution = (count as max - count as min) * element valueSum all contributions of every element to get the final answer.To efficiently find next/previous greater and next/previous smaller elements, we use monotonic stacks. 
            C++

    #include <iostream>
#include <vector>
#include <stack>
using namespace std;

int subarrayRanges(vector<int>& arr) {
    int n = arr.size();
    vector<int> leftMin(n), rightMin(n);
    vector<int> leftMax(n), rightMax(n);

    stack<int> st;

    // previous Smaller Element (leftMin)
    for (int i = 0; i < n; i++) {
        while (!st.empty() && arr[st.top()] > arr[i]) st.pop();
        leftMin[i] = st.empty() ? i + 1 : i - st.top();
        st.push(i);
    }

    while (!st.empty()) st.pop();

    // next Smaller Element (rightMin)
    for (int i = n - 1; i >= 0; i--) {
        while (!st.empty() && arr[st.top()] >= arr[i]) st.pop();
        rightMin[i] = st.empty() ? n - i : st.top() - i;
        st.push(i);
    }

    while (!st.empty()) st.pop();

    // previous Greater Element (leftMax)
    for (int i = 0; i < n; i++) {
        while (!st.empty() && arr[st.top()] < arr[i]) st.pop();
        leftMax[i] = st.empty() ? i + 1 : i - st.top();
        st.push(i);
    }

    while (!st.empty()) st.pop();

    // next Greater Element (rightMax)
    for (int i = n - 1; i >= 0; i--) {
        while (!st.empty() && arr[st.top()] <= arr[i]) st.pop();
        rightMax[i] = st.empty() ? n - i : st.top() - i;
        st.push(i);
    }

    // calculate total contribution
    int totalSum = 0;
    for (int i = 0; i < n; i++) {
        int maxContri = leftMax[i] * rightMax[i] * arr[i];
        int minContri = leftMin[i] * rightMin[i] * arr[i];
        totalSum += (maxContri - minContri);
    }

    return totalSum;
}

int main() {
    vector<int> arr = {1, 2, 3};
    cout << subarrayRanges(arr) << endl;
    return 0;
}


